INSERT INTO "_PermissionToRole" ("A", "B")
SELECT permission."id", role."id"
FROM role_defaults defaults
JOIN "Role" role ON role."name" = defaults.role_name
CROSS JOIN LATERAL unnest(defaults.permission_codes) AS permission_code
JOIN "Permission" permission ON permission."code" = permission_code
ON CONFLICT ("A", "B") DO NOTHING;

